"""Brute‑force solver for the Dominating Set problem.

Instance format follows :class:`DominatingSet` in ``problems.py``:
    {"n": n, "edges": [[u, v], ...], "k": k}
"""

from __future__ import annotations

from itertools import combinations
from typing import Dict, List, Set, Tuple


def solve(instance: Dict) -> bool:
    n: int = instance["n"]
    edges: List[List[int]] = instance["edges"]
    k: int = instance["k"]
    if k < 0:
        return False
    if n == 0:
        return True
    if k >= n:
        return True
    # Build adjacency list
    adj: List[Set[int]] = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # Precompute closed neighborhood for each vertex (itself + neighbors)
    closed: List[Set[int]] = [set([i]) | adj[i] for i in range(n)]
    # Try all subsets up to size k
    vertices = list(range(n))
    for size in range(k + 1):
        for combo in combinations(vertices, size):
            dominated: Set[int] = set()
            for v in combo:
                dominated |= closed[v]
            if len(dominated) == n:
                return True
    return False

EOF"}

